"""Fetch municipality outlines (OpenStreetMap via Nominatim, ODbL) for the OPERA Valencia AOI. Run once; output cached in munis_osm.json."""
import json, time, urllib.parse, urllib.request
NAMES = ["València","Paiporta","Picanya","Torrent","Catarroja","Massanassa","Alfafar","Benetússer","Sedaví","Albal",
 "Beniparrell","Silla","Alcàsser","Picassent","Sollana","Sueca","Albalat de la Ribera","Polinyà de Xúquer","Algemesí","Almussafes","Benifaió",
 "Alginet","Xirivella","Aldaia","Alaquàs","Quart de Poblet","Manises","Mislata","Paterna","Burjassot","Godelleta","Turís",
 "Montserrat","Montroi","Real","Llombai","Alfarp","Catadau","Riba-roja de Túria","Loriguilla","Cullera","Favara","Alboraia","Tavernes Blanques",
 "Alfara del Patriarca","Moncada","Godella","Rocafort","Vinalesa","Meliana","Foios","Almàssera","Bonrepòs i Mirambell","Llaurí","Corbera","Riola","Fortaleny","Alzira","Carlet","Benimodo","L'Alcúdia","Massalavés","Albalat dels Sorells","Museros","Emperador","Massamagrell","Pobla de Farnals","Massalfassar"]
out = {}
for n in dict.fromkeys(NAMES):
    q = urllib.parse.urlencode({"q": f"{n}, Valencia, Spain", "format": "json", "polygon_geojson": 1, "polygon_threshold": 0.0003, "limit": 3, "featuretype": "settlement"})
    req = urllib.request.Request("https://nominatim.openstreetmap.org/search?" + q, headers={"User-Agent": "spaceapps-sar-change/1.0 (NASA Space Apps 2026 research demo)"})
    try: d = json.load(urllib.request.urlopen(req, timeout=30))
    except Exception as ex: print("ERR", n, ex); time.sleep(1.2); continue
    hit = next((x for x in d if x.get("osm_type") == "relation" and x["geojson"]["type"] in ("Polygon", "MultiPolygon")), None)
    if hit: out[n] = {"osm_id": hit["osm_id"], "display": hit["display_name"], "geojson": hit["geojson"]}
    else: print("MISS", n)
    time.sleep(1.1)
open("munis_osm.py", "w").write("# Municipality outlines, OpenStreetMap contributors (ODbL), via Nominatim. Generated by fetch_munis.py.\nMUNIS = " + json.dumps(out, ensure_ascii=False) + "\n"); print(len(out))
